const crypto = require('crypto');
const input = $('Webhook Upload').first().json;

// Extract file info from body
let file_name = 'contract.docx';
let contract_type = 'nueva_planta';

if (input.body) {
  file_name = input.body.file_name || input.body.fileName || 'contract.docx';
  contract_type = input.body.contract_type || input.body.contractType || 'nueva_planta';
}

// Determine mime_type from extension
let mime_type = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
if (file_name.toLowerCase().endsWith('.pdf')) {
  mime_type = 'application/pdf';
}

const document_id = crypto.randomUUID();
const storage_path = `contracts/${document_id}/${file_name}`;

return [{
  json: {
    document_id,
    file_name,
    mime_type,
    storage_path,
    contract_type,
    tenant_id: '00000000-0000-0000-0000-000000000001'
  }
}];

const docData = $('Create Document').first().json;
const resolvedBlueprint = $('Resolve Blueprint').first().json;

// Check if blueprint was resolved
let blueprint_version_id = null;
let contract_model_version_id = null;
let blueprint_name = 'Default';
let blueprint_version_label = 'v1';

if (resolvedBlueprint && resolvedBlueprint.blueprint_version_id) {
  blueprint_version_id = resolvedBlueprint.blueprint_version_id;
  contract_model_version_id = resolvedBlueprint.contract_model_version_id || null;
  blueprint_name = resolvedBlueprint.blueprint_name || 'Amazon PSA/DSA';
  blueprint_version_label = resolvedBlueprint.blueprint_version_label || 'v1';
} else {
  // Fallback: try to get any active blueprint
  console.log('No blueprint found for contract_type: ' + docData.contract_type + '. Using fallback.');
}

return [{
  json: {
    ...docData,
    blueprint_version_id,
    contract_model_version_id,
    blueprint_name,
    blueprint_version_label,
    resolved_at: new Date().toISOString()
  }
}];

